// ─── REPORTS VIEW ─────────────────────────────────────────────────────────────
function ReportsView({cases}) {
  const [sortBy, setSortBy] = useState("checkoutDate");
  const [search, setSearch] = useState("");
  useEffect(()=>window.scrollTo({top:0,behavior:"smooth"}),[sortBy]);

  const SORTS = [
    ["collectionDate","COLLECTION DATE"],
    ["prepType","PREP TYPE"],
    ["funeralDir","FUNERAL DIRECTOR"],
    ["transferTeam","TRANSFER TEAM"],
    ["lastName","LAST NAME"],
    ["status","STATUS"],
  ];
  const STATUS_FILTERS=["ALL","NOT STARTED","IN PROGRESS","READY"];
  const [statusFilter,setStatusFilter]=useState("ALL");

  // ── Weekly Report: Friday 5:01pm to this Friday 5:00pm ─────────────────────
  function getWeeklyWindow() {
    const now = new Date();
    // Find last Friday 5:01pm
    const day = now.getDay(); // 0=Sun, 5=Fri
    const daysToLastFri = day >= 5 ? day - 5 : day + 2;
    const lastFri = new Date(now);
    lastFri.setDate(now.getDate() - daysToLastFri);
    lastFri.setHours(17, 1, 0, 0);
    // This Friday 5:00pm
    const thisFri = new Date(lastFri);
    thisFri.setDate(lastFri.getDate() + 7);
    thisFri.setHours(17, 0, 0, 0);
    return { from: lastFri, to: thisFri };
  }

  function downloadWeeklyReport() {
    const { from, to } = getWeeklyWindow();
    const weekly = cases.filter(c => {
      if(!c.checkout?.checkedOutAt) return false;
      const d = new Date(c.checkout.checkedOutAt);
      return d >= from && d <= to;
    }).sort((a,b)=>new Date(a.checkout.checkedOutAt)-new Date(b.checkout.checkedOutAt));

    if(weekly.length === 0) {
      alert(`No check-outs found between:\n${from.toLocaleString("en-AU")} and ${to.toLocaleString("en-AU")}`);
      return;
    }

    // Build CSV with formatting
    const fromStr = from.toLocaleDateString("en-AU",{day:"2-digit",month:"2-digit",year:"numeric"});
    const toStr = to.toLocaleDateString("en-AU",{day:"2-digit",month:"2-digit",year:"numeric"});

    const headers = [
      "Case Ref","Last Name","First Name","DOB","DOD","Age at Death","Sex",
      "Funeral Director","Preparation","Disposition","Destination",
      "Checked In","Checked In By","Check In Role",
      "Transferred From","Transferred By","Transfer Person","Paperwork","Valuables",
      "Checked Out","Checked Out By","Signed By","Viewing"
    ];

    const rows = weekly.map(c => {
      const prep = c.prep||{};
      const co = c.checkout||{};
      return [
        c.caseRef||"",
        c.lastName||"",
        c.firstName||"",
        fmt(c.dob),
        fmt(c.dod),
        c.ageAtDeath!==null&&c.ageAtDeath!==undefined?c.ageAtDeath:"",
        c.sex||"",
        c.funeralHomeName||"",
        (prep.prepOptions||[]).map(p=>PREP_OPTIONS.find(x=>x.label===p)?.short||p).join(", ")||"",
        prep.disposition||"",
        co.destination||"",
        c.checkedInAt?new Date(c.checkedInAt).toLocaleString("en-AU"):"",
        c.checkedInBy||"",
        c.checkedInRole||"",
        c.transferredFrom||"",
        c.transferredBy||"",
        c.transferPersonName||"",
        c.paperwork||"",
        c.valuables||"",
        co.checkedOutAt?new Date(co.checkedOutAt).toLocaleString("en-AU"):"",
        co.checkedOutBy||"",
        co.signedName||"",
        prep.viewing||(prep.viewingSlot?"Yes":""),
      ];
    });

    // Build CSV string
    const title = `MSS WEEKLY CHECK-OUT REPORT — ${fromStr} to ${toStr}`;
    const csvLines = [
      [title],
      [`Generated: ${new Date().toLocaleString("en-AU")}`],
      [`Total Check-Outs: ${weekly.length}`],
      [],
      headers,
      ...rows
    ];

    const csv = csvLines.map(row =>
      row.map(cell => `"${String(cell).replace(/"/g,'""')}"`).join(",")
    ).join("\n");

    // Download
    const blob = new Blob(["\uFEFF"+csv], {type:"text/csv;charset=utf-8;"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `MSS_Weekly_Report_${fromStr.replace(/\//g,"-")}_to_${toStr.replace(/\//g,"-")}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

  const STATUS_ORDER={"not-started":0,"in-progress":1,"completed":2};
  function getSortValue(c, key) {
    switch(key) {
      case "collectionDate": return c.prep?.collectionDate || "9999";
      case "prepType":      return (c.prep?.prepOptions||[]).join(", ") || "—";
      case "funeralDir":    return c.funeralHomeName || "—";
      case "transferTeam":  return c.transferredBy || "—";
      case "lastName":      return c.lastName || "—";
      case "status":        return String(STATUS_ORDER[c.prepStatus||"not-started"]||0);
      default: return "—";
    }
  }

  function getSortLabel(c, key) {
    switch(key) {
      case "checkoutDate":  return c.checkout?.checkedOutAt ? fmtDT(c.checkout.checkedOutAt) : "Not checked out";
      case "prepType":      return (c.prep?.prepOptions||[]).map(p=>PREP_OPTIONS.find(x=>x.label===p)?.short||p).join(", ") || "No Prep";
      case "funeralDir":    return c.funeralHomeName || "—";
      case "transferTeam":  return c.transferredBy || "—";
      case "lastName":      return `${(c.lastName||"").toUpperCase()}, ${c.firstName}`;
      default: return "—";
    }
  }

  const filtered = cases
    .filter(c => {
      // Status filter
      if(statusFilter==="NOT STARTED"&&(c.prepStatus||"not-started")!=="not-started") return false;
      if(statusFilter==="IN PROGRESS"&&c.prepStatus!=="in-progress") return false;
      if(statusFilter==="READY"&&c.prepStatus!=="completed") return false;
      if(!search.trim()) return true;
      const q = search.toLowerCase();
      return `${c.firstName} ${c.lastName} ${c.caseRef} ${c.funeralHomeName} ${c.transferredBy} ${(c.prep?.prepOptions||[]).join(" ")}`.toLowerCase().includes(q);
    })
    .sort((a,b) => {
      const av = getSortValue(a, sortBy);
      const bv = getSortValue(b, sortBy);
      // Dates sort newest first, text sorts A-Z
      if(sortBy === "collectionDate") return av.localeCompare(bv);
      return av.localeCompare(bv);
    });

  // Group by sort value for visual separation
  const groups = [];
  let lastGroup = null;
  filtered.forEach(c => {
    const groupKey = getSortLabel(c, sortBy);
    if(groupKey !== lastGroup) { groups.push({ key: groupKey, cases: [] }); lastGroup = groupKey; }
    groups[groups.length-1].cases.push(c);
  });

  return (
    <div className="max-w-7xl mx-auto px-4 py-4">
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-2xl font-black text-gray-900">Reports</h2>
        <div className="flex items-center gap-3">
          <span className="text-sm text-gray-500">{filtered.length} cases</span>
          <button onClick={downloadWeeklyReport}
            className="px-4 py-2 rounded-xl bg-gray-900 hover:bg-gray-700 text-white font-black text-xs uppercase tracking-wide transition flex items-center gap-2">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M7 10l5 5 5-5M12 15V3"/></svg>
            WEEKLY REPORT
          </button>
        </div>
      </div>

      {/* Search */}
      <input className="w-full bg-white border border-gray-300 rounded-xl px-4 py-3 text-gray-900 text-base focus:outline-none focus:border-gray-800 transition placeholder-gray-400 mb-4"
        placeholder="Search by name, case ref, funeral home, transfer team…"
        value={search} onChange={e=>setSearch(e.target.value)}/>

      {/* Sort buttons */}
      <div className="mb-6">
        <p className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-3">Sort By</p>
        <div className="flex flex-wrap gap-2">
          {SORTS.map(([key,label])=>(
            <button key={key} onClick={()=>setSortBy(key)}
              className={`px-4 py-2.5 rounded-xl border-2 text-sm font-bold transition ${sortBy===key?"bg-gray-900 text-white border-gray-900":"bg-white text-gray-600 border-gray-300 hover:border-gray-700"}`}>
              {label}
            </button>
          ))}
        </div>
      </div>

      {filtered.length===0&&<p className="text-gray-400 text-center py-12">No cases found.</p>}

      {/* Grouped results */}
      <div className="space-y-6">
        {groups.map(group=>(
          <div key={group.key}>
            {/* Group header */}
            <div className="flex items-center gap-3 mb-3">
              <div className="text-xs font-black text-gray-500 uppercase tracking-widest bg-gray-100 rounded-lg px-3 py-1.5">{group.key}</div>
              <div className="text-xs text-gray-400">{group.cases.length} case{group.cases.length>1?"s":""}</div>
            </div>

            {/* Cases in group */}
            <div className="space-y-2">
              {group.cases.map(c=>(
                <div key={c.id} className="bg-white border border-gray-200 rounded-2xl p-4">
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-1">
                        <StatusDot status={c.prepStatus||"not-started"}/>
                        <span className="text-base font-black text-gray-900">{(c.lastName||"").toUpperCase()}, {c.firstName}</span>
                        <span className="text-xs font-bold text-gray-400">{c.caseRef}</span>
                        {c.checkedOut&&<span className="text-xs bg-gray-100 text-gray-500 border border-gray-200 rounded-full px-2 py-0.5 font-semibold">Departed</span>}
                        {c.status==="locked"&&<span className="text-xs bg-gray-900 text-white rounded-full px-2 py-0.5 font-semibold">Locked</span>}
                      </div>
                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-x-4 gap-y-0.5 text-xs text-gray-500 ml-6">
                        <span>FD: <span className="text-gray-800 font-medium">{c.funeralHomeName||"—"}</span></span>
                        <span>In: <span className="text-gray-800 font-medium">{fmtDT(c.checkedInAt)}</span></span>
                        <span>Out: <span className="text-gray-800 font-medium">{c.checkout?.checkedOutAt?fmtDT(c.checkout.checkedOutAt):"—"}</span></span>
                        <span>Prep: <span className="text-gray-800 font-medium">{(c.prep?.prepOptions||[]).map(p=>PREP_OPTIONS.find(x=>x.label===p)?.short||p).join(", ")||"—"}</span></span>
                        <span>Transfer: <span className="text-gray-800 font-medium">{c.transferredBy||"—"}</span></span>
                        <span>DOD: <span className="text-gray-800 font-medium">{fmt(c.dod)}</span></span>
                        {c.prep?.disposition&&<span>Disposition: <span className="text-gray-800 font-medium">{c.prep.disposition}</span></span>}
                        {c.checkout?.destination&&<span>Dest: <span className="text-gray-800 font-medium">{c.checkout.destination}</span></span>}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ─── CALENDAR PRINT ──────────────────────────────────────────────────────────
function printWeek(weekDates,slotMap,slots){
  const dayNames=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
  const months=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  function fmtDay(d){const x=new Date(d+"T12:00:00");return `${dayNames[x.getDay()]} ${x.getDate()} ${months[x.getMonth()]}`;}
  const pw=window.open("","_blank");
  const cols=weekDates.map(d=>`<th style="padding:6px 4px;font-size:11px;font-weight:700;border:1px solid #ccc;background:#f5f5f5;min-width:90px">${fmtDay(d)}</th>`).join("");

  function buildTable(roomKey,roomLabel,color){
    const bg=color==="green"?"#d1fae5":"#dbeafe";
    const border=color==="green"?"#059669":"#2563eb";
    const header=color==="green"?"background:#065f46;color:#fff":"background:#1e3a8a;color:#fff";
    const renderedRows=new Set();
    const rows=slots.map(slot=>{
      const cells=weekDates.map(d=>{
        const key=`${d}_${slot.hour}_${slot.half?"half":"full"}_${roomKey}`;
        const cellKey=`${d}_${slot.hour}_${slot.half}`;
        const b=slotMap[key];
        if(b?.isContinuation) return null;
        const rowSpan=b?.spanOf||1;
        if(!b) return `<td style="padding:4px;border:1px solid #eee;height:24px"></td>`;
        return `<td rowspan="${rowSpan}" style="padding:4px 6px;border:2px solid ${border};background:${bg};font-size:10px;font-weight:700;vertical-align:top">${b.label||""}${b.label2?`<br><span style="font-size:9px;font-weight:600">${b.label2}</span>`:""}</td>`;
      });
      const hasCells=cells.some(x=>x!==null);
      if(!hasCells) return "";
      return `<tr><td style="padding:4px 6px;border:1px solid #eee;font-size:10px;color:#666;white-space:nowrap;background:#fafafa">${slot.label}</td>${cells.filter(x=>x!==null).join("")}</tr>`;
    }).join("");
    return `<div style="margin-bottom:32px;page-break-inside:avoid"><div style="padding:14px 16px;margin-bottom:8px;${header};border-radius:6px"><div style="font-size:28px;font-weight:900;letter-spacing:3px;text-transform:uppercase">${roomLabel}</div><div style="font-size:13px;opacity:0.8;margin-top:4px">Week of ${fmtDay(weekDates[0])} — ${fmtDay(weekDates[6])}</div></div><table style="border-collapse:collapse;width:100%"><thead><tr><th style="padding:6px 4px;font-size:11px;font-weight:700;border:1px solid #ccc;background:#f5f5f5;width:55px">Time</th>${cols}</tr></thead><tbody>${rows}</tbody></table></div>`;
  }

  const vrTable=buildTable("ViewingRoom","Viewing Room","green");
  const fmTable=buildTable("FamilyRoom","Family Meeting Room","blue");

  pw.document.write(`<!DOCTYPE html><html><head><title>MSS Calendar</title><style>body{font-family:Arial,sans-serif;padding:20px}table{border-collapse:collapse;width:100%}@media print{body{padding:10px}}</style></head><body><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;border-bottom:2px solid #111;padding-bottom:10px"><div style="font-size:20px;font-weight:900">MSS Mortuary Support Services</div><div style="font-size:12px;color:#666">Week of ${fmtDay(weekDates[0])} — ${fmtDay(weekDates[6])}</div></div>${vrTable}${fmTable}</body></html>`);
  pw.document.close();
  pw.focus();
  setTimeout(()=>pw.print(),400);
}

// ─── VEHICLE WEEK VIEW (embedded in Calendar) ────────────────────────────────
function VehicleWeekView({weekDates,vehicleBookings,onAddVehicleBooking,onUpdateVehicleBooking,onDeleteVehicleBooking,user,cases,readOnly=false}){
  const isFDUser=user?.role==="fd";
  const fdCaseIds=isFDUser?new Set(cases.filter(c=>c.funeralHomeId===user.funeralHomeId).map(c=>c.id)):null;
  const filteredVehicleBookings=vehicleBookings;
  const[showModal,setShowModal]=useState(false);
  const[editingBooking,setEditingBooking]=useState(null);
  const[showCompleteModal,setShowCompleteModal]=useState(null);
  const[saving,setSaving]=useState(false);
  const[jobType,setJobType]=useState(VEHICLE_JOB_TYPES[0].label);
  const[jobDate,setJobDate]=useState(weekDates[0]);
  const[jobTime,setJobTime]=useState("08:00");
  const[jobHours,setJobHours]=useState(1);
  const[assignedStaff,setAssignedStaff]=useState([]);
  const[caseId,setCaseId]=useState("");
  const[tbc,setTbc]=useState(false);
  const[notes,setNotes]=useState("");
  const[timeIn,setTimeIn]=useState("");
  const[timeOut,setTimeOut]=useState("");
  const[fuelLevel,setFuelLevel]=useState("F");
  const[cleanliness,setCleanliness]=useState("Clean");
  const[completionNotes,setCompletionNotes]=useState("");

  const activeCases=cases.filter(c=>c.status==="active"&&!c.checkedOut);
  const bookingsByDate={};
  weekDates.forEach(d=>bookingsByDate[d]=[]);
  (filteredVehicleBookings||[]).forEach(b=>{if(bookingsByDate[b.date])bookingsByDate[b.date].push(b);});
  weekDates.forEach(d=>bookingsByDate[d].sort((a,b2)=>a.time.localeCompare(b2.time)));

  const dayNames=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
  const months=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  function fmtD(d){const x=new Date(d+"T12:00:00");return`${dayNames[x.getDay()]} ${x.getDate()} ${months[x.getMonth()]}`;}

  function resetModal(){setShowModal(false);setEditingBooking(null);setJobType(VEHICLE_JOB_TYPES[0].label);setJobDate(weekDates[0]);setJobTime("08:00");setJobHours(1);setAssignedStaff([]);setCaseId("");setTbc(false);setNotes("");}
  function openEdit(b){setEditingBooking(b);setJobType(b.job_type);setJobDate(b.date);setJobTime(b.time);setJobHours(b.hours);setAssignedStaff(b.staff||[]);setCaseId(b.case_id||"");setTbc(b.tbc||false);setNotes(b.notes||"");setShowModal(true);}
  function toggleStaff(s){setAssignedStaff(prev=>prev.includes(s)?prev.filter(x=>x!==s):[...prev,s]);}

  async function saveBooking(){
    if(!jobDate||!jobTime||assignedStaff.length===0){alert("Please select date, time and at least one staff member.");return;}
   // Clash detection
   const newStart=jobTime;
   const [nh,nm]=(jobTime||"00:00").split(":").map(Number);
   const newStartMins=nh*60+nm;
   const newEndMins=newStartMins+(jobHours||1)*60;
   const newVehicle=VEHICLE_JOB_TYPES.find(j=>j.label===jobType)?.vehicle;
   const clashes=[];
   (vehicleBookings||[]).filter(b=>b.date===jobDate&&(!editingBooking||b.id!==editingBooking.id)).forEach(b=>{
     const [bh,bm]=(b.time||"00:00").split(":").map(Number);
     const bStart=bh*60+bm;
     const bEnd=bStart+(b.hours||1)*60;
     const overlaps=newStartMins<bEnd&&newEndMins>bStart;
     if(!overlaps) return;
     // Check staff clash
     const staffClash=assignedStaff.filter(s=>(b.staff||[]).includes(s));
     if(staffClash.length>0) clashes.push(`${staffClash.join(", ")} already booked at this time`);
     // Check vehicle clash
     const bVehicle=VEHICLE_JOB_TYPES.find(j=>j.label===b.job_type)?.vehicle;
     if(newVehicle&&bVehicle&&newVehicle===bVehicle) clashes.push(`${newVehicle} already booked at this time`);
   });
   if(clashes.length>0){alert("⚠ Booking clash detected:\n\n"+[...new Set(clashes)].join("\n")+"\n\nPlease choose a different time or staff member.");return;}
   setSaving(true);
   try{
     const selCase=activeCases.find(x=>x.id===caseId);
     const data={job_type:jobType,date:jobDate,time:jobTime,hours:jobHours,staff:assignedStaff,case_id:tbc?"":caseId,tbc,case_label:tbc?"TBC":selCase?`${(selCase.lastName||"").toUpperCase()}, ${selCase.firstName}`:"",funeral_home:selCase?.funeralHomeName||"",notes,completed:false,created_by:user?.name||"",created_at:new Date().toISOString()};
     if(editingBooking){
        await sb(`vehicle_bookings?id=eq.${editingBooking.id}`,{method:"PATCH",body:JSON.stringify(data),prefer:"return=representation"});
        onUpdateVehicleBooking({...editingBooking,...data});
      } else {
        const booking={id:genId(),...data};
        await sb("vehicle_bookings",{method:"POST",body:JSON.stringify(booking),prefer:"return=representation"});
        onAddVehicleBooking(booking);
      }
      resetModal();
    }catch(err){alert("Error: "+err.message);}
    setSaving(false);
  }

  async function completeJob(b){
    if(!timeIn||!timeOut){alert("Please enter time in and time out.");return;}
    setSaving(true);
    try{
      const data={completed:true,completedAt:new Date().toISOString(),time_in:timeIn,time_out:timeOut,fuel_level:fuelLevel,cleanliness,completion_notes:completionNotes};
      await sb(`vehicle_bookings?id=eq.${b.id}`,{method:"PATCH",body:JSON.stringify(data)});
      onUpdateVehicleBooking({...b,...data});
      setShowCompleteModal(null);setTimeIn("");setTimeOut("");setFuelLevel("F");setCleanliness("Clean");setCompletionNotes("");
    }catch(err){alert("Error: "+err.message);}
    setSaving(false);
  }

  async function deleteBooking(b){if(!window.confirm("Delete this booking?"))return;await sb(`vehicle_bookings?id=eq.${b.id}`,{method:"DELETE"});onDeleteVehicleBooking(b.id);resetModal();}

  // Build vehicle slot map (by hour slots like room calendar)
  const vSlotMap={};
  (vehicleBookings||[]).forEach(b=>{
    if(!weekDates.includes(b.date)) return;
    const[hStr,mStr]=(b.time||"08:00").split(":");
    const hour=parseInt(hStr);
    const isHalf=parseInt(mStr||0)>=30;
    const totalSlots=Math.ceil((b.hours||1)*2);
    let h=hour,half=isHalf;
    for(let i=0;i<totalSlots;i++){
      const key=`${b.date}_${h}_${half?"half":"full"}`;
      vSlotMap[key]={booking:b,isFirst:i===0,isContinuation:i>0,spanOf:totalSlots,
        label:i===0?b.job_type:"",label2:i===0?(b.case_label||"TBC"):"",
        staff:i===0?(b.staff||[]).join(", "):"",completed:b.completed};
      if(half){half=false;h++;}else{half=true;}
    }
  });

  return(
    <div>
      {!readOnly&&<button onClick={()=>setShowModal(true)} className="mb-4 px-5 py-2.5 rounded-xl bg-gray-900 text-white font-black text-sm uppercase hover:bg-gray-700 transition">+ ADD JOB</button>}
      <div className="overflow-x-auto">
        <table style={{minWidth:"600px",width:"100%",borderCollapse:"collapse",tableLayout:"fixed"}}>
          <thead>
            <tr>
              <th style={{width:"56px",padding:"4px",fontSize:"10px",color:"#9ca3af",textAlign:"left",fontWeight:"900",textTransform:"uppercase"}}>TIME</th>
              {weekDates.map(d=>{const dd=new Date(d+"T12:00:00");const isToday=d===todaySydney();return<th key={d} style={{padding:"4px",textAlign:"center",backgroundColor:isToday?"#111":"#f3f4f6",color:isToday?"#fff":"#374151",borderRadius:"6px",fontSize:"11px",fontWeight:"900",textTransform:"uppercase"}}>{dd.toLocaleDateString("en-AU",{weekday:"short"})}<br/><span style={{fontSize:"10px"}}>{dd.toLocaleDateString("en-AU",{day:"numeric",month:"short"})}</span></th>;})}
            </tr>
          </thead>
          <tbody>
          {(()=>{
            return CALENDAR_SLOTS.map(({hour,half,label})=>(
              <tr key={label}>
                <td style={{fontSize:"10px",fontWeight:"900",color:half?"#d1d5db":"#6b7280",padding:"2px 4px",verticalAlign:"top",whiteSpace:"nowrap"}}>{label}</td>
                {weekDates.map(date=>{
                  const key=`${date}_${hour}_${half?"half":"full"}`;
                  const slot=vSlotMap[key];
                  if(slot?.isContinuation) return <td key={date} style={{padding:0,border:"none"}}/>;
                  if(slot){
                    const rowSpan=slot.spanOf||1;
                    const isMine=!isFDUser||(isFDUser&&!!slot.booking?.case_id&&fdCaseIds?.has(slot.booking.case_id));
                    const bg=!isMine?"#f3f4f6":slot.completed?"#dcfce7":"#f8fafc";
                    const border=!isMine?"#e5e7eb":slot.completed?"#16a34a":"#6b7280";
                    const textColor=!isMine?"#9ca3af":slot.completed?"#166534":"#1f2937";
                    return(
                      <td key={date} rowSpan={rowSpan} style={{padding:"2px",backgroundColor:bg,border:`2px solid ${border}`,borderRadius:"4px",verticalAlign:"top",opacity:isMine?1:0.5}}>
                        <div style={{padding:"2px 4px"}}>
                          {!isMine?<div style={{fontSize:"9px",color:"#9ca3af",fontWeight:"700",textAlign:"center"}}>BUSY</div>:<>
                          <div style={{fontSize:"10px",fontWeight:"900",textTransform:"uppercase",color:textColor,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{slot.label}</div>
                          <div style={{fontSize:"9px",color:"#6b7280",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{slot.label2}</div>
                          <div style={{fontSize:"9px",color:"#9ca3af",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{slot.staff}</div>
                          {slot.completed&&<div style={{fontSize:"9px",color:"#16a34a",fontWeight:"900"}}>✓ DONE</div>}
                          {!readOnly&&<div style={{display:"flex",gap:"2px",marginTop:"2px"}}>
                            <button onClick={()=>openEdit(slot.booking)} style={{flex:1,fontSize:"8px",padding:"1px",background:"#e5e7eb",border:"none",borderRadius:"3px",cursor:"pointer",fontWeight:"700"}}>EDIT</button>
                            {!slot.completed&&<button onClick={()=>setShowCompleteModal(slot.booking)} style={{flex:1,fontSize:"8px",padding:"1px",background:"#111",color:"#fff",border:"none",borderRadius:"3px",cursor:"pointer",fontWeight:"700"}}>DONE</button>}
                          </div>}
                          </>}
                        </div>
                      </td>
                    );
                  }
                  return <td key={date} style={{padding:"2px",backgroundColor:half?"#f9fafb":"#ffffff",border:"1px solid #f3f4f6",cursor:"pointer"}} onClick={()=>{setJobDate(date);setJobTime(label);setShowModal(true);}}><div style={{minHeight:"24px",textAlign:"center",color:"#e5e7eb",fontSize:"11px",fontWeight:"900"}}>+</div></td>;
                })}
              </tr>
            ));
          })()}
          </tbody>
        </table>
      </div>

      {showModal&&(
        <div style={{position:"fixed",inset:0,zIndex:9999,background:"rgba(0,0,0,0.6)",display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"20px",overflowY:"auto"}}>
          <div className="bg-white rounded-2xl p-6 shadow-xl w-full max-w-md">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-black text-gray-900 uppercase">{editingBooking?"EDIT JOB":"ADD JOB"}</h3>
              <button onClick={resetModal} className="text-gray-400 hover:text-gray-700 font-black text-xl">✕</button>
            </div>
            <div className="space-y-4">
              <div><div className="text-xs font-black uppercase text-gray-500 mb-1">Job Type</div>
                <select className="w-full border-2 border-gray-200 rounded-xl px-3 py-2 text-sm font-bold" value={jobType} onChange={e=>{setJobType(e.target.value);const jt=VEHICLE_JOB_TYPES.find(x=>x.label===e.target.value);if(jt)setJobHours(jt.defaultHours);}}>
                  {VEHICLE_JOB_TYPES.map(j=><option key={j.label}>{j.label}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div><div className="text-xs font-black uppercase text-gray-500 mb-1">Date</div><input type="date" className="w-full border-2 border-gray-200 rounded-xl px-3 py-2 text-sm" value={jobDate} onChange={e=>setJobDate(e.target.value)}/></div>
                <div><div className="text-xs font-black uppercase text-gray-500 mb-1">Start Time</div><input type="time" className="w-full border-2 border-gray-200 rounded-xl px-3 py-2 text-sm" value={jobTime} onChange={e=>setJobTime(e.target.value)}/></div>
              </div>
              <div><div className="text-xs font-black uppercase text-gray-500 mb-1">Duration (hours)</div><input type="number" min="0.5" max="12" step="0.5" className="w-full border-2 border-gray-200 rounded-xl px-3 py-2 text-sm" value={jobHours} onChange={e=>setJobHours(parseFloat(e.target.value))}/></div>
              <div><div className="text-xs font-black uppercase text-gray-500 mb-2">Assign Staff</div>
                <div className="flex flex-wrap gap-2">{VEHICLE_STAFF.map(s=><button key={s} type="button" onClick={()=>toggleStaff(s)} className={`px-3 py-1.5 rounded-xl border-2 text-xs font-black transition ${assignedStaff.includes(s)?"bg-gray-900 text-white border-gray-900":"border-gray-200 text-gray-600 hover:border-gray-700"}`}>{s}</button>)}</div>
              </div>
              <div><div className="text-xs font-black uppercase text-gray-500 mb-1">Case</div>
                <div className="flex items-center gap-2">
                  <button type="button" onClick={()=>setTbc(!tbc)} className={`px-3 py-1.5 rounded-xl border-2 text-xs font-black transition ${tbc?"bg-amber-500 text-white border-amber-500":"border-gray-200 text-gray-600"}`}>TBC</button>
                  {!tbc&&<select className="flex-1 border-2 border-gray-200 rounded-xl px-3 py-2 text-sm" value={caseId} onChange={e=>setCaseId(e.target.value)}>
                    <option value="">— Select Case —</option>
                    {activeCases.sort((a,b2)=>a.lastName.localeCompare(b2.lastName)).map(x=><option key={x.id} value={x.id}>{(x.lastName||"").toUpperCase()}, {x.firstName} — {x.funeralHomeName}</option>)}
                  </select>}
                </div>
              </div>
              <div><div className="text-xs font-black uppercase text-gray-500 mb-1">Notes</div><textarea className="w-full border-2 border-gray-200 rounded-xl px-3 py-2 text-sm" rows={2} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Additional notes..."/></div>
              <div className="flex gap-3">
                <button onClick={saveBooking} disabled={saving} className="flex-1 py-3 rounded-xl bg-gray-900 text-white font-black text-sm uppercase">{saving?"SAVING...":"SAVE"}</button>
                {editingBooking&&<button onClick={()=>deleteBooking(editingBooking)} className="px-4 py-3 rounded-xl border-2 border-red-300 text-red-500 font-black text-sm">DELETE</button>}
              </div>
            </div>
          </div>
        </div>
      )}

      {showCompleteModal&&(
        <div style={{position:"fixed",inset:0,zIndex:9999,background:"rgba(0,0,0,0.6)",display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"20px",overflowY:"auto"}}>
          <div className="bg-white rounded-2xl p-6 shadow-xl w-full max-w-md">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-black text-gray-900 uppercase">Complete Job</h3>
              <button onClick={()=>setShowCompleteModal(null)} className="text-gray-400 hover:text-gray-700 font-black text-xl">✕</button>
            </div>
            <div className="bg-gray-50 rounded-xl p-3 mb-4 text-sm">
              <div className="font-black">{showCompleteModal.jobType}</div>
              <div className="text-gray-500">{showCompleteModal.caseLabel||"TBC"} · {showCompleteModal.date} {showCompleteModal.time}</div>
              <div className="text-gray-400">{(showCompleteModal.staff||[]).join(", ")}</div>
            </div>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div><div className="text-xs font-black uppercase text-gray-500 mb-1">Time In</div><input type="time" className="w-full border-2 border-gray-200 rounded-xl px-3 py-2 text-sm" value={timeIn} onChange={e=>setTimeIn(e.target.value)}/></div>
                <div><div className="text-xs font-black uppercase text-gray-500 mb-1">Time Out</div><input type="time" className="w-full border-2 border-gray-200 rounded-xl px-3 py-2 text-sm" value={timeOut} onChange={e=>setTimeOut(e.target.value)}/></div>
              </div>
              <div><div className="text-xs font-black uppercase text-gray-500 mb-2">Fuel Level</div>
                <div className="flex gap-2">{FUEL_LEVELS.map(f=><button key={f} type="button" onClick={()=>setFuelLevel(f)} className={`flex-1 py-2 rounded-xl border-2 text-xs font-black transition ${fuelLevel===f?"bg-gray-900 text-white border-gray-900":"border-gray-200 text-gray-600"}`}>{f}</button>)}</div>
              </div>
              <div><div className="text-xs font-black uppercase text-gray-500 mb-2">Cleanliness</div>
                <div className="flex gap-2">{CLEANLINESS.map(cl=><button key={cl} type="button" onClick={()=>setCleanliness(cl)} className={`flex-1 py-2 rounded-xl border-2 text-xs font-black transition ${cleanliness===cl?(cl==="Clean"?"bg-green-600 text-white border-green-600":cl==="Dusty"?"bg-amber-500 text-white border-amber-500":"bg-red-500 text-white border-red-500"):"border-gray-200 text-gray-600"}`}>{cl}</button>)}</div>
              </div>
              <div><div className="text-xs font-black uppercase text-gray-500 mb-1">Comments</div><textarea className="w-full border-2 border-gray-200 rounded-xl px-3 py-2 text-sm" rows={3} value={completionNotes} onChange={e=>setCompletionNotes(e.target.value)} placeholder="Notes about job or vehicle..."/></div>
              <button onClick={()=>completeJob(showCompleteModal)} disabled={saving} className="w-full py-3 rounded-xl bg-green-600 text-white font-black text-sm uppercase">{saving?"SAVING...":"✓ MARK COMPLETE"}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ─── CALENDAR ─────────────────────────────────────────────────────────────────
const CALENDAR_SLOTS=[];
for(let h=8;h<=20;h++){
  CALENDAR_SLOTS.push({hour:h,half:false,label:`${String(h).padStart(2,"0")}:00`});
  if(h<20) CALENDAR_SLOTS.push({hour:h,half:true,label:`${String(h).padStart(2,"0")}:30`});
}

function getWeekDates(base){
  const dates=[];
  const d=new Date(base+"T12:00:00");
  if(isNaN(d.getTime())) return Array(7).fill(todaySydney());
  const day=d.getDay();
  const diff=day===0?-6:1-day; // Start Monday
  d.setDate(d.getDate()+diff);
  for(let i=0;i<7;i++){const dd=new Date(d);dd.setDate(d.getDate()+i);dates.push(dd.toISOString().slice(0,10));}
  return dates;
}

function CalendarView({user,cases,calendarBookings,onAddBooking,onUpdateBooking,onDeleteBooking,vehicleBookings,onAddVehicleBooking,onUpdateVehicleBooking,onDeleteVehicleBooking,defaultTab}){
  const isAdmin=user?.role==="admin";
  const isMSS=user?.role==="mss"||isAdmin;
  const[weekBase,setWeekBase]=useState(today());
  const[showBookModal,setShowBookModal]=useState(false);
  const[editingBooking,setEditingBooking]=useState(null); // booking being viewed/edited
  const[bookSlot,setBookSlot]=useState(null);
  const[bookDuration,setBookDuration]=useState("1 HOUR");
  const[activeRoom,setActiveRoom]=useState(defaultTab||"ViewingRoom");
  const[bookType,setBookType]=useState("Viewing Room");
  const[careType,setCareType]=useState("");
  const[selFHId,setSelFHId]=useState("");
  const[selCaseId,setSelCaseId]=useState("");
  const[notInCareRef,setNotInCareRef]=useState("");
  const[saving,setSaving]=useState(false);
  useEffect(()=>window.scrollTo({top:0,behavior:"smooth"}),[]);

  const isFD=user?.role==="fd";
  const canEdit=user?.role==="admin"||user?.role==="mss"||user?.role==="fd";
  const weekDates=getWeekDates(weekBase);

  function prevWeek(){const d=new Date(weekDates[0]);d.setDate(d.getDate()-7);setWeekBase(d.toISOString().slice(0,10));}
  function nextWeek(){const d=new Date(weekDates[0]);d.setDate(d.getDate()+7);setWeekBase(d.toISOString().slice(0,10));}

  function resetModal(){
    setShowBookModal(false);setEditingBooking(null);setBookSlot(null);
    setCareType("");setSelFHId("");setSelCaseId("");setNotInCareRef("");
    setBookType("Viewing Room");setBookDuration("1 HOUR");
  }

  function openEdit(booking){
    setEditingBooking(booking);
    setBookSlot(booking.slot);
    setBookType(booking.type||"Viewing Room");
    setBookDuration(booking.duration||"1 HOUR");
    setCareType(booking.care_type||"");
    setSelFHId(booking.funeral_home_id||"");
    setSelCaseId(booking.case_id||"");
    setNotInCareRef(booking.not_in_care_ref||"");
    setShowBookModal(true);
  }

  const slotMap={};
  cases.filter(c=>c.prep?.viewingSlot&&c.prep?.viewing==="Yes").forEach(c=>{
    const slot=c.prep.viewingSlot;
    const[date,time]=slot.split("_");
    const isHalf=time.includes(":30");
    const hour=parseInt(time.split(":")[0]);
    const key=`${date}_${hour}_${isHalf?"half":"full"}_ViewingRoom`;
    const fhName1=FUNERAL_HOMES.find(f=>f.id===c.funeralHomeId)?.name||c.funeralHomeName||"";
    const vDurRaw=c.prep?.viewingDuration||"1 HR";
    const vDur=vDurRaw==="2 HR"?"2 HOURS":"1 HOUR";
    const vSlots=vDur==="2 HOURS"?4:2;
    let vh=hour,vhalf=isHalf;
    for(let vi=0;vi<vSlots;vi++){
      const vkey=`${date}_${vh}_${vhalf?"half":"full"}_ViewingRoom`;
      slotMap[vkey]={type:"Viewing Room",label:vi===0?fhName1:"",label2:vi===0?(c.lastName||"").toUpperCase():"",fhId:c.funeralHomeId,color:"green",fromCase:true,isFirst:vi===0,isContinuation:vi>0,spanOf:vSlots,caseId:c.id,caseRef:c.caseRef,funeralHomeId:c.funeralHomeId};
      if(vhalf){vhalf=false;vh++;}else{vhalf=true;}
    }
  });
  (calendarBookings||[]).forEach(b=>{
    const[date,time]=b.slot.split("_");
    const isHalf=time.includes(":30");
    const hour=parseInt(time.split(":")[0]);
    const dur=b.duration||"1 HOUR";
    const slots=dur==="2 HOURS"?4:dur==="1 HOUR"?2:1;
    const labelParts=(b.deceased_label||b.type).split(" — ");
    const label=labelParts[0];
    const label2=labelParts[1]||"";
    const color=b.type==="Viewing Room"?"green":"blue";
    // Fill all slots for the duration
    const roomKey=b.type==="Viewing Room"?"ViewingRoom":"FamilyRoom";
    let h=hour,half=isHalf;
    for(let i=0;i<slots;i++){
      const key=`${date}_${h}_${half?"half":"full"}_${roomKey}`;
      slotMap[key]={type:b.type,label:i===0?label:"",label2:i===0?label2:"",fhId:b.funeral_home_id||null,color,bookingId:b.id,booking:b,isFirst:i===0,isContinuation:i>0,spanOf:slots};
      if(half){half=false;h++;}else{half=true;}
    }
  });

  const activeCases=cases.filter(c=>c.status==="active"&&!c.checkedOut);
  const casesByFH={};
  activeCases.forEach(c=>{if(!casesByFH[c.funeralHomeId])casesByFH[c.funeralHomeId]=[];casesByFH[c.funeralHomeId].push(c);});
  const fhsWithCases=sortAlpha(FUNERAL_HOMES.filter(f=>casesByFH[f.id]?.length>0),"name");
  const fhCasesForSel=selFHId?(casesByFH[selFHId]||[]).sort((a,b)=>a.lastName.localeCompare(b.lastName)):[];

  function getBookingLabel(){
    if(careType==="in-care"&&selCaseId){const cx=cases.find(x=>x.id===selCaseId);if(cx){const fhN=FUNERAL_HOMES.find(f=>f.id===cx.funeralHomeId)?.name||cx.funeralHomeName||"";return`${fhN} — ${(cx.lastName||"").toUpperCase()}`;}return"";}
    if(careType==="not-in-care"&&selFHId&&notInCareRef){const fh=FUNERAL_HOMES.find(f=>f.id===selFHId);return`${fh?.name||""} - ${notInCareRef}`;}
    return bookType;
  }

  const canConfirm=bookSlot&&bookType&&bookDuration&&careType&&(careType==="in-care"?!!selCaseId:(!!selFHId&&notInCareRef.trim().length>0));

  async function confirmBooking(){
    if(!canConfirm)return;
    setSaving(true);
    try{
      const fhId=careType==="in-care"?cases.find(c=>c.id===selCaseId)?.funeralHomeId:selFHId;
      const data={slot:bookSlot,type:bookType,duration:bookDuration,funeral_home_id:fhId||null,deceased_label:getBookingLabel(),care_type:careType,case_id:careType==="in-care"?selCaseId:null,not_in_care_ref:careType==="not-in-care"?notInCareRef:null,booked_by:user.name};

      if(editingBooking){
        // Update existing booking
        await sb(`calendar_bookings?id=eq.${editingBooking.id}`,{method:"PATCH",body:JSON.stringify(data),prefer:"return=representation"});
        onUpdateBooking({...editingBooking,...data});
      } else {
        // New booking
        const booking={id:genId(),...data,booked_at:new Date().toISOString()};
        await insertCalendarBooking(booking);
        onAddBooking(booking);
      }
      resetModal();
    }catch(err){alert("Booking error: "+err.message);}
    setSaving(false);
  }

  async function removeBooking(bookingId){
    if(!window.confirm("Remove this booking?"))return;
    try{await deleteCalendarBooking(bookingId);onDeleteBooking(bookingId);resetModal();}
    catch(err){alert("Error: "+err.message);}
  }

  // Check if current user can edit a slot
  function canEditSlot(slot){
    if(!slot) return false;
    if(slot.fromCase) return canEdit; // admin/mss can edit mortuary viewings
    if(canEdit) return true; // admin/mss can always edit
    if(isFD&&slot.fhId===user.funeralHomeId) return true; // FD can edit their own
    return false;
  }

  function handleSlotClick(slot,slotId,room){
    if(!slot){
      if(canEdit){
        setBookSlot(slotId);
        if(room==="FamilyRoom")setBookType("Family Meeting Room");
        else setBookType("Viewing Room");
        setShowBookModal(true);
      }
      return;
    }
    if(slot.fromCase){
      if(canEdit){
        setEditingBooking({...slot,isMortuaryBooking:true,label:slot.label});
        setBookSlot(slotId);
        setShowBookModal(true);
      }
      return;
    }
    if(canEditSlot(slot)){
      openEdit(slot.booking);
    } else if(isFD&&slot.fhId!==user.funeralHomeId){
      // Other FD booking — show busy, no action
    }
  }

  return(
    <div className="w-full px-4 py-6">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-2xl font-black text-gray-900 uppercase">Calendar</h2>
        <div className="flex items-center gap-2">
          <button onClick={prevWeek} className={`${s.btnGhost} py-2 px-4`}>← PREV</button>
          <span className="text-xs font-black text-gray-600 uppercase px-2">{fmt(weekDates[0])} – {fmt(weekDates[6])}</span>
          <button onClick={nextWeek} className={`${s.btnDark} py-2 px-4`}>NEXT →</button>
        </div>
      </div>

      <div className="flex gap-4 mb-4">
        <div className="flex items-center gap-2"><div className="w-4 h-4 rounded bg-green-500"/><span className="text-xs font-black uppercase text-gray-600">Viewing Room</span></div>
        <div className="flex items-center gap-2"><div className="w-4 h-4 rounded bg-blue-500"/><span className="text-xs font-black uppercase text-gray-600">Family Meeting Room</span></div>
        {isFD&&<div className="flex items-center gap-2"><div className="w-4 h-4 rounded bg-gray-300"/><span className="text-xs font-black uppercase text-gray-600">Unavailable</span></div>}
      </div>

      <div className="flex gap-3 mb-5">
        {canEdit&&<button onClick={()=>{resetModal();setShowBookModal(true);}} className={`${s.btnDark} py-3`}>+ BOOK A ROOM</button>}
        {(isAdmin||user?.role==="mss")&&activeRoom!=="VehicleStaff"&&<button onClick={()=>setActiveRoom("VehicleStaff")} className={`${s.btnGhost} py-3`}>+ ADD JOB</button>}
        <button onClick={()=>printWeek(weekDates,slotMap,CALENDAR_SLOTS)} className={`${s.btnGhost} py-3`}>🖨️ PRINT WEEK</button>
      </div>

      {/* Room Tabs */}
      <div className="flex flex-wrap gap-2 mb-4">
        {[["ViewingRoom","Viewing Room","green"],["FamilyRoom","Family Meeting Room","blue"],["VehicleStaff","Vehicle & Staff","gray"]].map(([key,label,color])=>(
          <button key={key} onClick={()=>setActiveRoom(key)}
            className={"px-4 py-2.5 rounded-xl border-2 font-black text-sm uppercase transition "+(activeRoom===key?(color==="green"?"bg-green-600 text-white border-green-600":color==="blue"?"bg-blue-600 text-white border-blue-600":"bg-gray-900 text-white border-gray-900"):"border-gray-200 text-gray-600 hover:border-gray-700")}>
            {label}
          </button>
        ))}
      </div>

      {activeRoom!=="VehicleStaff"&&<div className="overflow-x-auto">
        <table style={{minWidth:"600px",width:"100%",borderCollapse:"collapse",tableLayout:"fixed"}}>
          <thead>
            <tr>
              <th style={{width:"56px",padding:"4px",fontSize:"10px",color:"#9ca3af",textAlign:"left",fontWeight:"900",textTransform:"uppercase"}}>TIME</th>
              {weekDates.map(d=>{const dd=new Date(d);const isToday=d===today();return<th key={d} style={{padding:"4px",textAlign:"center",backgroundColor:isToday?"#111":"#f3f4f6",color:isToday?"#fff":"#374151",borderRadius:"6px",fontSize:"11px",fontWeight:"900",textTransform:"uppercase"}}>{dd.toLocaleDateString("en-AU",{weekday:"short"})}<br/><span style={{fontSize:"10px"}}>{dd.toLocaleDateString("en-AU",{day:"numeric",month:"short"})}</span></th>;})}
            </tr>
          </thead>
          <tbody>
          {(()=>{
            const roomKey=activeRoom;
            const renderedKeys=new Set();
            return CALENDAR_SLOTS.map(({hour,half,label})=>{
            return(
            <tr key={label}>
              <td style={{fontSize:"10px",fontWeight:"900",color:half?"#d1d5db":"#6b7280",padding:"2px 4px",verticalAlign:"top",whiteSpace:"nowrap"}}>{label}</td>
              {weekDates.map(date=>{
                const key=`${date}_${hour}_${half?"half":"full"}_${activeRoom}`;
                const slot=slotMap[key];
                const slotId=`${date}_${label}`;
                const editable=canEditSlot(slot)||(isFD&&slot?.fhId===user.funeralHomeId);

                // Skip continuation slots - handled by rowSpan
                if(slot?.isContinuation) return <td key={date} style={{padding:0,border:"none"}}/>;

                if(slot){
                  const rowSpan=slot.spanOf||1;
                  const bgColor=slot.color==="green"?"#dcfce7":"#dbeafe";
                  const borderColor=slot.color==="green"?"#16a34a":"#2563eb";
                  const textColor=slot.color==="green"?"#166534":"#1e40af";
                  const isMine=!isFD||(slot.fhId===user.funeralHomeId);
                  if(isFD&&!isMine) return <td key={date} rowSpan={rowSpan} style={{padding:"2px",backgroundColor:"#e5e7eb",fontSize:"10px",textAlign:"center",color:"#9ca3af",fontWeight:"700"}}>BUSY</td>;
                  return(
                    <td key={date} rowSpan={rowSpan} style={{padding:"2px",backgroundColor:bgColor,border:`2px solid ${borderColor}`,borderRadius:"4px",verticalAlign:"top"}}>
                      <button onClick={()=>handleSlotClick(slot,slotId)} style={{width:"100%",height:"100%",minHeight:"24px",background:"transparent",border:"none",cursor:"pointer",textAlign:"left",padding:"2px 4px",color:textColor}}>
                        <span style={{display:"block",fontSize:"11px",fontWeight:"700",textTransform:"uppercase",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{slot.label}</span>
                        {slot.label2&&<span style={{display:"block",fontSize:"10px",fontWeight:"600",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",opacity:0.85}}>{slot.label2}</span>}
                        {!slot.fromCase&&<span style={{display:"block",fontSize:"9px",opacity:0.7}}>{slot.booking?.duration||""}</span>}
                        {!slot.fromCase&&canEdit&&<span style={{display:"block",fontSize:"9px",opacity:0.5}}>TAP TO EDIT</span>}
                      </button>
                    </td>
                  );
                }

                return canEdit
                  ?<td key={date} style={{padding:"2px",backgroundColor:half?"#f9fafb":"#ffffff",border:"1px solid #f3f4f6"}}>
                    <button onClick={()=>handleSlotClick(null,slotId,activeRoom)} style={{width:"100%",minHeight:"24px",background:"transparent",border:"none",cursor:"pointer",color:"#d1d5db",fontWeight:"900",fontSize:"12px",textAlign:"center"}}>+</button>
                  </td>
                  :<td key={date} style={{padding:"2px",backgroundColor:half?"#f9fafb":"#ffffff",border:"1px solid #f3f4f6"}}/>;
              })}
            </tr>
            );
          });
          })()}
          </tbody>
        </table>
      </div>}
      {activeRoom==="VehicleStaff"&&<VehicleWeekView weekDates={weekDates} vehicleBookings={vehicleBookings} onAddVehicleBooking={onAddVehicleBooking} onUpdateVehicleBooking={onUpdateVehicleBooking} onDeleteVehicleBooking={onDeleteVehicleBooking} user={user} cases={cases} readOnly={isFD}/>}

      {/* Book / Edit Modal */}
      {showBookModal&&(canEdit||isFD)&&(
        <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/40 pt-6 px-4 overflow-y-auto">
          <div className="bg-white border border-gray-200 rounded-2xl p-6 shadow-xl w-full max-w-md mb-8">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-black text-gray-900 uppercase">{editingBooking?"EDIT BOOKING":"BOOK A ROOM"}</h3>
              <button onClick={resetModal} className="text-gray-400 hover:text-gray-700 font-black text-xl leading-none">✕</button>
            </div>

            {/* Slot */}
            {/* Date picker */}
            <div className="mb-3">
              <label className={s.label}>DATE</label>
              <input type="date" className={s.inp}
                value={bookSlot?bookSlot.split("_")[0]:""}
                onChange={e=>{
                  const d=e.target.value;
                  const t=bookSlot?bookSlot.split("_")[1]:"09:00";
                  if(d) setBookSlot(`${d}_${t}`);
                }}/>
            </div>
            {/* Time picker — hour buttons */}
            <div className="mb-3">
              <label className={s.label}>START TIME</label>
              <div className="grid grid-cols-3 sm:grid-cols-4 gap-1.5">
                {["09:00","09:30","10:00","10:30","11:00","11:30","12:00","12:30","13:00","13:30","14:00","14:30","15:00","15:30","16:00","16:30","17:00","17:30","18:00","18:30","19:00","19:30","20:00","20:30"].map(t=>{
                  const cur=bookSlot?bookSlot.split("_")[1]:"";
                  const d=bookSlot?bookSlot.split("_")[0]:today();
                  return(
                    <button key={t} type="button" onClick={()=>setBookSlot(`${d}_${t}`)}
                      className={`py-2 rounded-lg border-2 text-xs font-black uppercase transition ${cur===t?"bg-gray-900 text-white border-gray-900":"bg-white text-gray-600 border-gray-200 hover:border-gray-600"}`}>
                      {t}
                    </button>
                  );
                })}
              </div>
            </div>
            {/* Duration */}
            <div className="mb-4">
              <label className={s.label}>DURATION</label>
              <div className="flex flex-wrap gap-2">
                {["1 HOUR","2 HOURS"].map(d=>(
                  <button key={d} type="button" onClick={()=>setBookDuration(d)}
                    className={`flex-1 py-3 rounded-xl border-2 font-black text-sm uppercase transition ${bookDuration===d?"bg-gray-900 text-white border-gray-900":"border-gray-300 text-gray-600 hover:border-gray-700"}`}>
                    {d}
                  </button>
                ))}
              </div>
            </div>
            {bookSlot&&(
              <div className="bg-gray-50 border border-gray-200 rounded-xl px-4 py-2 mb-3">
                <span className="text-xs font-black text-gray-500 uppercase">BOOKED: </span>
                <span className="text-sm font-black text-gray-900 uppercase">{fmt(bookSlot.split("_")[0])} AT {bookSlot.split("_")[1]} — {bookDuration}</span>
              </div>
            )}

            {/* Room type */}
            <div className="mb-4">
              <label className={s.label}>ROOM TYPE</label>
              <div className="flex flex-wrap gap-2">
                <button onClick={()=>setBookType("Viewing Room")} className={`flex-1 py-3 rounded-xl border-2 font-black text-sm uppercase transition ${bookType==="Viewing Room"?"bg-green-600 text-white border-green-600":"border-gray-300 text-gray-600 hover:border-gray-700"}`}>VIEWING ROOM</button>
                <button onClick={()=>setBookType("Family Meeting Room")} className={`flex-1 py-3 rounded-xl border-2 font-black text-sm uppercase transition ${bookType==="Family Meeting Room"?"bg-blue-600 text-white border-blue-600":"border-gray-300 text-gray-600 hover:border-gray-700"}`}>FAMILY MEETING</button>
              </div>
            </div>

            {/* Deceased status — FD only sees their own cases */}
            <div className="mb-4">
              <label className={s.label}>DECEASED STATUS</label>
              <div className="flex gap-2 mb-3">
                <button onClick={()=>{setCareType("in-care");setSelFHId(isFD?user.funeralHomeId:"");setSelCaseId("");setNotInCareRef("");}} className={`flex-1 py-3 rounded-xl border-2 font-black text-sm uppercase transition ${careType==="in-care"?"bg-gray-900 text-white border-gray-900":"border-gray-300 text-gray-600 hover:border-gray-700"}`}>IN CARE</button>
                <button onClick={()=>{setCareType("not-in-care");setSelFHId(isFD?user.funeralHomeId:"");setSelCaseId("");setNotInCareRef("");}} className={`flex-1 py-3 rounded-xl border-2 font-black text-sm uppercase transition ${careType==="not-in-care"?"bg-gray-900 text-white border-gray-900":"border-gray-300 text-gray-600 hover:border-gray-700"}`}>NOT IN CARE</button>
              </div>

              {careType==="in-care"&&(
                <div>
                  {!isFD&&(
                    <div className="mb-3">
                      <label className={s.label}>FUNERAL DIRECTOR</label>
                      <div className="flex flex-wrap gap-2">
                        {fhsWithCases.length===0&&<p className="text-xs font-bold text-gray-400 uppercase">No active cases</p>}
                        {fhsWithCases.map(fh=><button key={fh.id} onClick={()=>{setSelFHId(fh.id);setSelCaseId("");}} className={s.tb(selFHId===fh.id)}>{fh.name}</button>)}
                      </div>
                    </div>
                  )}
                  {selFHId&&(casesByFH[selFHId]||[]).length>0&&(
                    <div>
                      <label className={s.label}>SELECT DECEASED</label>
                      <div className="flex flex-col gap-2">
                        {(casesByFH[selFHId]||[]).sort((a,b)=>a.lastName.localeCompare(b.lastName)).map(c=>(
                          <button key={c.id} onClick={()=>setSelCaseId(c.id)} className={`py-3 px-4 rounded-xl border-2 font-black text-sm uppercase text-left transition ${selCaseId===c.id?"bg-gray-900 text-white border-gray-900":"border-gray-200 hover:border-gray-700"}`}>
                            {(c.lastName||"").toUpperCase()}, {c.firstName}
                          </button>
                        ))}
                      </div>
                    </div>
                  )}
                  {selFHId&&(casesByFH[selFHId]||[]).length===0&&<p className="text-xs font-bold text-gray-400 uppercase">No active cases for this FD</p>}
                </div>
              )}

              {careType==="not-in-care"&&(
                <div>
                  {!isFD&&(
                    <div className="mb-3">
                      <label className={s.label}>FUNERAL DIRECTOR</label>
                      <div className="flex flex-wrap gap-2">
                        {sortAlpha(FUNERAL_HOMES,"name").map(fh=><button key={fh.id} onClick={()=>{setSelFHId(fh.id);setNotInCareRef("");}} className={s.tb(selFHId===fh.id)}>{fh.name}</button>)}
                      </div>
                    </div>
                  )}
                  {selFHId&&(
                    <div>
                      <label className={s.label}>REF: NAME</label>
                      <input className={s.inp} placeholder="Enter reference name…" value={notInCareRef} onChange={e=>setNotInCareRef(e.target.value)}/>
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Booking details summary if editing */}
            {editingBooking&&(
              <div className="bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 mb-4 text-xs font-bold text-gray-600 uppercase">
                <div>Booked by: {editingBooking.booked_by}</div>
                <div>Date: {fmtDT(editingBooking.booked_at)}</div>
              </div>
            )}

            <div className="flex gap-3 pt-3 border-t border-gray-100">
              {editingBooking&&(
                <button onClick={()=>removeBooking(editingBooking.id)} className="px-4 py-3 rounded-xl border-2 border-red-300 text-red-600 font-black text-sm uppercase hover:bg-red-50 transition">DELETE</button>
              )}
              <button onClick={resetModal} className={`${s.btnGhost} flex-1 py-3`}>CANCEL</button>
              <button onClick={confirmBooking} disabled={!canConfirm||saving} className={`${s.btnDark} flex-1 py-3 disabled:opacity-40`}>{saving?"SAVING…":editingBooking?"SAVE CHANGES":"CONFIRM"}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}



// ─── APP ──────────────────────────────────────────────────────────────────────
const getCalendarBookings=()=>sb("calendar_bookings?select=*").catch(()=>[]);
const getVehicleBookings=()=>sb("vehicle_bookings?select=*&order=date.asc,time.asc").catch(()=>[]);
const insertCalendarBooking=b=>sb("calendar_bookings",{method:"POST",body:JSON.stringify(b),prefer:"return=representation"});
const deleteCalendarBooking=id=>sb(`calendar_bookings?id=eq.${id}`,{method:"DELETE"});

class ErrorBoundary extends React.Component{
  constructor(p){super(p);this.state={error:null};}
  static getDerivedStateFromError(e){return{error:e};}
  render(){
    if(this.state.error)return(
      <div style={{padding:"40px",textAlign:"center"}}>
        <h2 style={{color:"#dc2626",fontWeight:"900"}}>Something went wrong</h2>
        <p style={{color:"#6b7280",marginTop:"8px",fontSize:"14px"}}>{this.state.error.message}</p>
        <button onClick={()=>this.setState({error:null})} style={{marginTop:"16px",padding:"10px 24px",background:"#111",color:"#fff",border:"none",borderRadius:"8px",cursor:"pointer",fontWeight:"700"}}>Go Back</button>
      </div>
    );
    return this.props.children;
  }
}

export default function App() {
  const [users,setUsers]=useState([]);
  const [maintenanceMode,setMaintenanceMode]=useState(null);

  useEffect(()=>{
    async function checkMaintenance(){
      try{
        const res=await sb("app_settings?key=eq.maintenance_mode&select=value");
        const data=await res.json();
        if(data?.[0]?.value==="true") setMaintenanceMode(true);
        else setMaintenanceMode(false);
      }catch(e){}
    }
    checkMaintenance();
    const interval=setInterval(checkMaintenance,30000);
    return()=>clearInterval(interval);
  },[]);

  async function toggleMaintenance(){
    const newVal=(!maintenanceMode).toString();
    try{
      await sb("app_settings?key=eq.maintenance_mode",{method:"PATCH",body:JSON.stringify({value:newVal,updated_at:new Date().toISOString()}),prefer:"return=representation"});
      setMaintenanceMode(!maintenanceMode);
    }catch(e){alert("Error: "+e.message);}
  }
  const [cases,setCases]=useState([]);
  const [calendarBookings,setCalendarBookings]=useState([]);
  const [vehicleBookings,setVehicleBookings]=useState([]);
  const [loading,setLoading]=useState(true);
  const [user,setUser]=useState(null);
  const [tab,setTab]=useState("home");
  const [showTimeoutModal,setShowTimeoutModal]=useState(false);
  const [lockOpen,setLockOpen]=useState(false);
  const [action,setAction]=useState(null);
  useEffect(()=>{window.scrollTo({top:0,behavior:"smooth"});},[tab,action]);

  useEffect(()=>{
    function preventTabScroll(e){
      if(e.key==="Tab"){e.preventDefault();const focusable=document.querySelectorAll('button, input, select, textarea, a[href]');const arr=Array.from(focusable).filter(el=>!el.disabled&&el.offsetParent!==null);const idx=arr.indexOf(document.activeElement);const next=e.shiftKey?arr[idx-1]||arr[arr.length-1]:arr[idx+1]||arr[0];if(next)next.focus({preventScroll:true});}
    }
    document.addEventListener("keydown",preventTabScroll);
    return()=>document.removeEventListener("keydown",preventTabScroll);
  },[]);

  useEffect(()=>{
    Promise.all([getUsers(),getCases(),getCalendarBookings(),getVehicleBookings()]).then(([u,c,b,vb])=>{
      setUsers(u);
      setCases(c.map(dbToCase));
      setCalendarBookings(b||[]);
      setVehicleBookings(Array.isArray(vb)?vb:[]);
    }).catch(err=>console.error("Load error:",err))
    .finally(()=>setLoading(false));
  },[]);

  function handleLogin(u){setUser(u);setTab("home");setAction(null);window.scrollTo({top:0,behavior:"instant"});refreshCaseViewers();setInterval(refreshCaseViewers,10000);
    if(!window.google){const s=document.createElement("script");s.src="https://maps.googleapis.com/maps/api/js?key=AIzaSyBm4OXgCFjqu9iRekbLQPloDg9WTE_Kd3o&libraries=places";document.head.appendChild(s);}}
  useEffect(()=>{function sendHeight(){window.parent.postMessage({height:document.body.scrollHeight},"*");} sendHeight();const o=new ResizeObserver(sendHeight);o.observe(document.body);return()=>o.disconnect();},[]);
  function handleLogout(){if(user)logActivity(user,"LOGOUT","User signed out");setUser(null);setTab("home");setAction(null);}

  // Auto-logout after 2 minutes of inactivity
  useEffect(()=>{
    if(!user) return;
    let timer;
    function reset(){
      clearTimeout(timer);
      timer=setTimeout(()=>{
        handleLogout();
        handleLogout();
      }, 5 * 60 * 1000);
    }
    const events=["mousedown","mousemove","keydown","scroll","touchstart","click"];
    events.forEach(e=>window.addEventListener(e,reset));
    reset(); // start timer
    return()=>{
      clearTimeout(timer);
      events.forEach(e=>window.removeEventListener(e,reset));
    };
  },[user]);
  function handleComplete(r){setCases(prev=>[r,...prev]);setAction(null);window.scrollTo({top:0,behavior:"smooth"});}
  function handleUpdateCase(id,updates){setCases(prev=>prev.map(c=>c.id===id?{...c,...updates}:c));}
  function handlePinUpdate(uid,pin){setUsers(prev=>prev.map(u=>u.id===uid?{...u,pin}:u));}
  function handleAddBooking(b){setCalendarBookings(prev=>[...prev,b]);}
  function handleAddVehicleBooking(b){setVehicleBookings(prev=>[...prev,b]);}
  function handleUpdateVehicleBooking(b){setVehicleBookings(prev=>prev.map(x=>x.id===b.id?b:x));}
  function handleDeleteVehicleBooking(id){setVehicleBookings(prev=>prev.filter(x=>x.id!==id));}
  function handleUpdateBooking(b){setCalendarBookings(prev=>prev.map(x=>x.id===b.id?b:x));}
  function handleDeleteBooking(id){setCalendarBookings(prev=>prev.filter(b=>b.id!==id));}

  if(loading) return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center">
      <div className="text-center">
        <MSSLogo size="md"/>
        <div className="mt-8"><Spinner/></div>
        <p className="text-gray-400 text-sm font-bold uppercase mt-4">Loading…</p>
      </div>
    </div>
  );

  if(!user){
    if(maintenanceMode===true) return(
      <div style={{minHeight:"100vh",background:"#111",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:"32px",textAlign:"center"}}>
        <div style={{fontSize:"48px",marginBottom:"16px"}}>🔧</div>
        <h1 style={{color:"#fff",fontSize:"24px",fontWeight:"900",marginBottom:"8px",letterSpacing:"2px",textTransform:"uppercase"}}>System Upgrade in Progress</h1>
        <p style={{color:"#9ca3af",fontSize:"14px",maxWidth:"320px",lineHeight:"1.6"}}>We are currently making improvements to the system. Please check back shortly.</p>
        <p style={{color:"#6b7280",fontSize:"11px",marginTop:"24px",letterSpacing:"1px",textTransform:"uppercase"}}>Mortuary Support | Lumière</p>
      </div>
    );
    return <LoginScreen onLogin={handleLogin} users={users} maintenanceMode={maintenanceMode}/>;
  }
  if(maintenanceMode&&user?.role!=="admin") return(
    <div style={{minHeight:"100vh",background:"#111",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:"32px",textAlign:"center"}}>
      <div style={{fontSize:"48px",marginBottom:"16px"}}>🔧</div>
      <h1 style={{color:"#fff",fontSize:"24px",fontWeight:"900",marginBottom:"8px",letterSpacing:"2px",textTransform:"uppercase"}}>System Upgrade in Progress</h1>
      <p style={{color:"#9ca3af",fontSize:"14px",maxWidth:"320px",lineHeight:"1.6"}}>We are currently making improvements to the system. Please check back shortly.</p>
      <button onClick={handleLogout} style={{marginTop:"24px",padding:"10px 24px",background:"#333",color:"#fff",border:"none",borderRadius:"10px",cursor:"pointer",fontSize:"12px",fontWeight:"700",textTransform:"uppercase",letterSpacing:"1px"}}>Sign Out</button>
    </div>
  );

  const isAdmin=user.role==="admin";
  const isMSS=user.role==="mss"||isAdmin;
  const isFD=user.role==="fd";
  const isTransfer=user.role==="transfer";

  const wrap=(children)=>(
    <div className="min-h-screen bg-gray-50 flex flex-col" style={{WebkitOverflowScrolling:"touch",overflowX:"clip"}}>
      {showTimeoutModal&&(
        <div style={{position:"fixed",inset:0,zIndex:9999,background:"rgba(0,0,0,0.7)",display:"flex",alignItems:"center",justifyContent:"center",padding:"16px"}}>
          <div style={{background:"#fff",borderRadius:"20px",padding:"32px",maxWidth:"340px",width:"100%",textAlign:"center",boxShadow:"0 20px 60px rgba(0,0,0,0.3)"}}>
            <div style={{fontSize:"40px",marginBottom:"12px"}}>⏱</div>
            <h2 style={{fontSize:"20px",fontWeight:"900",color:"#111",marginBottom:"8px"}}>Timeout Has Occurred</h2>
            <p style={{fontSize:"14px",color:"#6b7280",marginBottom:"24px"}}>You have been logged out. Please log back in to continue.</p>
            <button onClick={()=>{setShowTimeoutModal(false);handleLogout();}} style={{width:"100%",padding:"14px",background:"#111",color:"#fff",border:"none",borderRadius:"12px",fontSize:"14px",fontWeight:"900",cursor:"pointer",textTransform:"uppercase",letterSpacing:"1px"}}>Log Back In</button>
          </div>
        </div>
      )}
      <Header user={user} onSignOut={handleLogout} onNav={t=>{setTab(t);setAction(null);}} activeTab={tab}/>
      <div style={{paddingTop:"56px"}}>{children}</div>
    </div>
  );

  if(action==="reports") return wrap(<ReportsView cases={cases}/>);
  if(action==="approvals") return wrap(<ApprovalsView user={user} cases={cases} onUpdateCase={handleUpdateCase} onBack={()=>setAction(null)}/>);
  if(action==="lockview") return wrap(<ErrorBoundary><LockView user={user} cases={cases} onUpdateCase={handleUpdateCase} onBack={()=>setAction(null)}/></ErrorBoundary>);
  if(action==="checkin") return wrap(<CheckInFlow user={user} cases={cases} onComplete={handleComplete} onBack={()=>setAction(null)}/>);
  if(action==="newcheckins") return wrap(<NewCheckInsView cases={cases} onAction={a=>{setAction(a);}} user={user}/>);
  if(action==="ashes"&&(isAdmin||isMSS)) return wrap(<AshesRegister user={user} cases={cases} onBack={()=>setAction(null)}/>);
  if(action==="ashes"&&(isAdmin||isMSS)) return wrap(<AshesRegister user={user} cases={cases} onBack={()=>setAction(null)}/>);
  if(action==="ashes"&&(isAdmin||isMSS)) return wrap(<AshesRegister user={user} cases={cases} onBack={()=>setAction(null)}/>);
  if(action==="mastercalendar"&&(isAdmin||isMSS)) return wrap(<MasterCalendar cases={cases} calendarBookings={calendarBookings} vehicleBookings={vehicleBookings}/>);
  if(action==="dashboard") return wrap(<AdminDashboard cases={cases} calendarBookings={calendarBookings} onAction={a=>{setAction(a);window.scrollTo({top:0,behavior:"smooth"});}}/>);
  if(action==="pins"&&isAdmin) return wrap(<PinManagement users={users} onPinUpdate={handlePinUpdate}/>);
  if(action==="activitylog"&&isAdmin) return wrap(<ActivityLogView/>);
  if(action==="invoicing"&&isAdmin) return wrap(<ErrorBoundary><InvoicingView user={user} cases={cases} onUpdateCase={handleUpdateCase}/></ErrorBoundary>);
  if(action==="changes") return wrap(<ChangesView cases={cases} onUpdateCase={handleUpdateCase}/>);
  if(action==="vehicles") return wrap(<ErrorBoundary><CalendarView user={user} cases={cases} calendarBookings={calendarBookings} onAddBooking={handleAddBooking} onUpdateBooking={handleUpdateBooking} onDeleteBooking={handleDeleteBooking} vehicleBookings={vehicleBookings} onAddVehicleBooking={handleAddVehicleBooking} onUpdateVehicleBooking={handleUpdateVehicleBooking} onDeleteVehicleBooking={handleDeleteVehicleBooking} defaultTab="VehicleStaff"/></ErrorBoundary>);
  if(action==="mortuary") return wrap(<MortuaryFlow user={user} cases={cases} onUpdateCase={handleUpdateCase} onBack={()=>setAction(null)}/>);
  if(action==="checkout") return wrap(<CheckOutFlow user={user} cases={cases} onUpdateCase={handleUpdateCase} onBack={()=>setAction(null)}/>);
  if(action==="mycases") return wrap(<MyCases user={user} cases={cases} onUpdateCase={handleUpdateCase}/>);
  if(action==="transfers") return wrap(<MyTransfers user={user} cases={cases}/>);
  if(action==="calendar") return wrap(<ErrorBoundary><CalendarView user={user} cases={cases} calendarBookings={calendarBookings} onAddBooking={handleAddBooking} onUpdateBooking={handleUpdateBooking} onDeleteBooking={handleDeleteBooking} vehicleBookings={vehicleBookings} onAddVehicleBooking={handleAddVehicleBooking} onUpdateVehicleBooking={handleUpdateVehicleBooking} onDeleteVehicleBooking={handleDeleteVehicleBooking}/></ErrorBoundary>);

  return wrap(
    <main>
      {tab==="home"&&<HomeScreen user={user} onAction={a=>setAction(a)}/>}
      {tab==="records"&&(isMSS||isAdmin)&&<RecordsView user={user} cases={cases} onUpdateCase={handleUpdateCase}/>}
      {tab==="reports"&&(isMSS||isAdmin)&&<ReportsView cases={cases}/>}
      {tab==="calendar"&&(isMSS||isAdmin||isFD)&&<CalendarView user={user} cases={cases} calendarBookings={calendarBookings} onAddBooking={handleAddBooking} onUpdateBooking={handleUpdateBooking} onDeleteBooking={handleDeleteBooking} vehicleBookings={vehicleBookings} onAddVehicleBooking={handleAddVehicleBooking} onUpdateVehicleBooking={handleUpdateVehicleBooking} onDeleteVehicleBooking={handleDeleteVehicleBooking}/>}
      {tab==="records"&&isFD&&<MyCases user={user} cases={cases} onUpdateCase={handleUpdateCase}/>}
      {tab==="mycases"&&isFD&&<MyCases user={user} cases={cases} onUpdateCase={handleUpdateCase}/>}
      {tab==="transfers"&&isTransfer&&<MyTransfers user={user} cases={cases}/>}
      {tab==="pins"&&isAdmin&&<PinManagement users={users} onPinUpdate={handlePinUpdate}/>
      }{tab==="activitylog"&&isAdmin&&<ActivityLogView/>}{tab==="dashboard"&&isAdmin&&<AdminDashboard cases={cases} calendarBookings={calendarBookings} onAction={a=>{setAction(a);window.scrollTo({top:0,behavior:"smooth"});}}/>}{tab==="invoicing"&&isAdmin&&<InvoicingView cases={cases} onUpdateCase={handleUpdateCase}/>}
      {tab==="mypin"&&isMSS&&!isAdmin&&<MyPin user={user} users={users}/>}
    </main>
  );
}
